#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long m;
    cin >> n >> m;

    vector<long long> lav(n);
    for (long long& x : lav) cin >> x;

    long long currentMax = *max_element(lav.begin(), lav.end());
    long long maximum = currentMax + m;
    long long low = currentMax, high = maximum;

    while (low < high) {
        long long mid = low + (high - low) / 2;
        long long capacity = 0;

        for (long long x : lav) {
            capacity += mid - x;
            if (capacity >= m) break;
        }

        if (capacity >= m)
            high = mid;
        else
            low = mid + 1;
    }

    cout << low << ' ' << maximum;
    return 0;
}

